/* Parent Component */
.card-container {
  container-type: inline-size;
  container-name: card-wrapper;
}

/* Child Component */
.card {
  display: flex;
  flex-direction: column;
}

/* Requirement: When container is wider than 400px, switch to row */

.gallery {
  display: flex;
  flex-wrap: wrap;
}

